fn program() -> ResolvedProgram {
    crate::hir::resolve(&crate::check(
        "module operands.owner; @id(\"main:é\") fn main()->i64 {let mut n=0;while n<3 {n=n+1;if n==1 {return 7;};0} return 9;}",
        "operand-owner.spx").unwrap()).unwrap()
